/** Identity to show for a pillar. Until cutover the tutoring network is still "Swift Skills" unless the stage is ascent-internal. */
export function aeroBrand(key: AeroBrandKey, stage?: string | null): AeroIdentity {
  const b = BRANDS[key];
  const legacy = b.legacy && stage !== ASCENT_STAGE ? b.legacy : null;
  const s = legacy ?? b;
  return {
    key, paletteKey: legacy ? legacy.key : key, legacy: !!legacy,
    name: s.name, code: s.code, role: s.role, domain: s.domain, url: s.url,
    primary: s.primary, secondary: s.secondary, tertiary: s.tertiary,
  };
}

/** Locked artwork for a pillar. */
export function aeroLogo(key: AeroBrandKey, variant: AeroLogoVariant, stage?: string | null): AeroLogoArt {
  const b = BRANDS[key];
  if (b.legacy && stage !== ASCENT_STAGE) return { viewBox: b.legacy.viewBox, nodes: b.legacy.mark };
  return { viewBox: '0 0 48 48', nodes: variant === 'isometric' ? b.isometric : b.kinetic };
}

/** Rows for the ecosystem switcher. urls overrides a pillar's link (local previews). */
export function aeroSwitcher(current: AeroBrandKey, stage?: string | null, urls?: Partial<Record<AeroBrandKey, string>>): AeroSwitcherItem[] {
  return AERO_SWITCHER.map((key) => {
    const b = aeroBrand(key, stage);
    return { ...b, href: urls?.[key] || b.url, current: key === current };
  });
}
